        // from the pre‐check above we know start+sub.len() ≤ main.len(),
        // so at each step start+i ≤ main.len() and indexing is safe
        #[invariant(start + sub.len() <= main.len() ==> start + i <= main.len())]
        // so far, no mismatch among the first `i` elements
